"""ResNet-34 (ImageNet) — Generated by Lean 4 → JAX
Architecture: Conv(3→64,7x7/2)+BN → Pool(3x3) → Res3(64→64,s1) → Res4(64→128,s2) → Res6(128→256,s2) → Res3(256→512,s2) → GAP → 512→1000
Parameters: 21797672
Matching: Convolutional Neural Networks with Swift for TensorFlow
"""
import jax
import jax.numpy as jnp
from jax import random, jit, value_and_grad
from jax.sharding import Mesh, NamedSharding, PartitionSpec as P
import numpy as np
import struct, os, time, json, collections

# ═══════════════════════════════════════════════════════════════════════
#  ImageNet streaming pipeline (tfds + tf.data)
# ═══════════════════════════════════════════════════════════════════════

import tensorflow as tf
tf.config.set_visible_devices([], 'GPU')  # keep TF off the GPUs
import tensorflow_datasets as tfds

_IMG_SIZE = 224
_CROP_PADDING = 32
_CROP_PCT = _IMG_SIZE / (_IMG_SIZE + _CROP_PADDING)   # 224/256 = 0.875, timm's default
_MEAN_RGB = tf.constant([0.485 * 255, 0.456 * 255, 0.406 * 255], dtype=tf.float32)
_STD_RGB  = tf.constant([0.229 * 255, 0.224 * 255, 0.225 * 255], dtype=tf.float32)
_AUG_SEED = os.environ.get('AUG_SEED')
_AUG_SEED = int(_AUG_SEED) if _AUG_SEED else None

def _imagenet_decode_random_crop_flip(image_bytes):
    shape = tf.io.extract_jpeg_shape(image_bytes)
    bbox = tf.constant([0.0, 0.0, 1.0, 1.0], dtype=tf.float32, shape=[1, 1, 4])
    bbox_begin, bbox_size, _ = tf.image.sample_distorted_bounding_box(
        shape, bounding_boxes=bbox,
        min_object_covered=0.1, aspect_ratio_range=(3./4, 4./3.),
        area_range=(0.08, 1.0), max_attempts=10,
        seed=_AUG_SEED,
        use_image_if_no_bounding_boxes=True)
    oy, ox, _ = tf.unstack(bbox_begin)
    th, tw, _ = tf.unstack(bbox_size)
    window = tf.stack([oy, ox, th, tw])
    img = tf.io.decode_and_crop_jpeg(image_bytes, window, channels=3)
    img = tf.image.resize([img], [_IMG_SIZE, _IMG_SIZE],
                          method=tf.image.ResizeMethod.BICUBIC, antialias=True)[0]
    img = tf.image.random_flip_left_right(img, seed=_AUG_SEED)
    return img

def _imagenet_decode_center_crop(image_bytes):
    img = tf.io.decode_jpeg(image_bytes, channels=3)
    shape = tf.shape(img)
    h, w = shape[0], shape[1]
    target = tf.cast(tf.round(_IMG_SIZE / _CROP_PCT), tf.int32)
    scale = tf.cast(target, tf.float32) / tf.cast(tf.minimum(h, w), tf.float32)
    nh = tf.cast(tf.round(tf.cast(h, tf.float32) * scale), tf.int32)
    nw = tf.cast(tf.round(tf.cast(w, tf.float32) * scale), tf.int32)
    img = tf.image.resize(img, [nh, nw], method=tf.image.ResizeMethod.BICUBIC,
                          antialias=True)   # PIL-equivalent; see the emitter's note
    oy = (nh - _IMG_SIZE) // 2
    ox = (nw - _IMG_SIZE) // 2
    return tf.image.crop_to_bounding_box(img, oy, ox, _IMG_SIZE, _IMG_SIZE)

def build_imagenet_iter(split, batch_size, training, augment, shard=None):
    ds = tfds.load('imagenet2012', split=split,
                   decoders={'image': tfds.decode.SkipDecoding()},
                   data_dir=os.environ.get('TFDS_DATA_DIR'))
    if shard is not None:
        ds = ds.shard(num_shards=shard[1], index=shard[0])
    def _pp(ex):
        b = ex['image']
        img = (_imagenet_decode_random_crop_flip(b)
               if (training and augment)
               else _imagenet_decode_center_crop(b))
        img = tf.cast(img, tf.float32)              # 0..255 HWC
        img = (img - _MEAN_RGB) / _STD_RGB          # normalize, still HWC
        img = tf.transpose(img, [2, 0, 1])          # HWC -> CHW
        img = tf.reshape(img, [3 * _IMG_SIZE * _IMG_SIZE])  # flat to match forward()
        return img, ex['label']
    if training:
        ds = ds.shuffle(8192, seed=42, reshuffle_each_iteration=True)
        ds = ds.repeat()
    ds = ds.map(_pp, num_parallel_calls=tf.data.AUTOTUNE)
    ds = ds.batch(batch_size, drop_remainder=training)
    ds = ds.prefetch(tf.data.AUTOTUNE)
    return tfds.as_numpy(ds)

def prefetch_to_device(it, sharding, depth=2):
    # Overlap host->device copies with compute: device_put is async, so
    # keeping `depth` batches in flight hides the H2D transfer behind the
    # previous train_step instead of serializing after it.
    q = collections.deque()
    for x, y in it:
        q.append((jax.device_put(x, sharding), jax.device_put(y, sharding)))
        if len(q) >= depth:
            yield q.popleft()
    while q:
        yield q.popleft()

# Matmul compute dtype (mixed precision). bf16 casts matmul operands and
# returns fp32; master weights / LayerNorm / softmax stay fp32.
# Helps matmul-bound nets (ViT/transformers ~2.7-3.6x on gfx1100).
DT = jnp.bfloat16
def mm(a, b):
    return (a.astype(DT) @ b.astype(DT)).astype(jnp.float32)

# Conv compute dtype. Independent of DT: convs stay fp32 on MIOpen/gfx1100
# (bf16 conv is slower there), but opt into bf16 on cuDNN/CUDA where tensor
# cores make bf16 conv ~1.6x faster. CONV_DT=float32 -> casts are no-ops.
CONV_DT = jnp.bfloat16
def convdt(x):
    return x.astype(CONV_DT)

# ═══════════════════════════════════════════════════════════════════════
#  Conv / Pool helpers
# ═══════════════════════════════════════════════════════════════════════

def conv2d(x, w, b, padding=None, stride=(1,1)):
    # He et al. / torchvision: SYMMETRIC padding (k-1)//2 — i.e. nn.Conv2d(padding=k//2)
    # — NOT XLA 'SAME'. This is the max_pool2d finding one op over, and it hides the
    # same way: the OUTPUT SHAPE is identical either way, so nothing ever fails.
    #
    # At stride 1 with an ODD kernel the two are BIT-IDENTICAL, which is every conv in
    # the repo except the strided ones — so cifar/mnist and all stride-1 layers are
    # provably unaffected. They differ only when STRIDED on an even input:
    #   7x7/s2 on 224: 'SAME' pads (2,3), symmetric (3,3)
    #   3x3/s2 on 56/28/14: 'SAME' pads (0,1), symmetric (1,1)
    #   1x1/s2: (0,0) both ways — projections are unaffected.
    # As with the pool, the two grids are offset by one input position.
    #
    # Changed 2026-08-04 for paper-faithfulness. ⚠ Scoped to the ResNet-family helpers
    # ON PURPOSE: MobileNetV2/EfficientNet emit their own conv_general_dilated with
    # 'SAME' and are TF-origin ports, where asymmetric 'SAME' IS the reference. Do not
    # 'fix' those. See planning/rsb_a3_r50_verified.md §4b.
    if padding is None:
        padding = (((w.shape[2] - 1) // 2,) * 2, ((w.shape[3] - 1) // 2,) * 2)
    x = jax.lax.conv_general_dilated(convdt(x), convdt(w), stride, padding,
          dimension_numbers=('NCHW', 'OIHW', 'NCHW')).astype(jnp.float32)
    return x + b.reshape(1, -1, 1, 1)

def max_pool2d(x, size=2, stride=2):
    # He et al. / torchvision: SYMMETRIC padding (size-1)//2 — i.e.
    # nn.MaxPool2d(size, stride, padding=(size-1)//2) — NOT XLA 'SAME'.
    #
    # At size=2 this is BIT-IDENTICAL to 'SAME' (p=0), so every 2x2 pool in the
    # repo (cifar/mnist) is unaffected — verified. It differs only at ODD kernels:
    # for 3x3/s2 on 112, 'SAME' pads (low=0, high=1) giving window i = [2i, 2i+2],
    # where the paper's symmetric pad gives [2i-1, 2i+1]. The two grids are offset
    # by one input position and are different functions everywhere (measured at
    # n=12: 'SAME' window maxima [2,4,6,8,10,11] vs symmetric [1,3,5,7,9,11]).
    # Output shape is unchanged (112 -> 56) either way.
    #
    # Changed 2026-08-03 for paper-faithfulness; see planning/rsb_a3_r50_verified.md.
    # This MOVES the ResNet stem pool, so it voids R34-ImageNet's and R50's numbers.
    p = (size - 1) // 2
    return jax.lax.reduce_window(x, -jnp.inf, jax.lax.max,
             (1, 1, size, size), (1, 1, stride, stride),
             ((0, 0), (0, 0), (p, p), (p, p)))

def _bn(x, gamma, beta, prev, training, eps=1e-5, momentum=0.99):
    rm, rv = prev
    if training:
        bm = jnp.mean(x, axis=(0, 2, 3)); bv = jnp.var(x, axis=(0, 2, 3))
        xn = (x - bm.reshape(1, -1, 1, 1)) / jnp.sqrt(bv.reshape(1, -1, 1, 1) + eps)
        new = (momentum * rm + (1.0 - momentum) * bm, momentum * rv + (1.0 - momentum) * bv)
    else:
        xn = (x - rm.reshape(1, -1, 1, 1)) / jnp.sqrt(rv.reshape(1, -1, 1, 1) + eps)
        new = (rm, rv)
    return xn * gamma.reshape(1, -1, 1, 1) + beta.reshape(1, -1, 1, 1), new

def conv_bn(x, w, gamma, beta, prev, training, stride=(1,1), padding=None):
    # SYMMETRIC (k-1)//2, not XLA 'SAME' — see conv2d for the full argument. Inert at
    # stride 1 with an odd kernel; moves ONLY the strided convs (R34: the 7x7/s2 stem
    # and the three 3x3/s2 stage entries).
    if padding is None:
        padding = (((w.shape[2] - 1) // 2,) * 2, ((w.shape[3] - 1) // 2,) * 2)
    x = jax.lax.conv_general_dilated(convdt(x), convdt(w), stride, padding,
          dimension_numbers=('NCHW', 'OIHW', 'NCHW')).astype(jnp.float32)
    return _bn(x, gamma, beta, prev, training)

# Per-BN-layer channel counts, in forward order (PyTorch-style init: mean 0, var 1).
_BN_CHANNELS = [64, 64, 64, 64, 64, 64, 64, 128, 128, 128, 128, 128, 128, 128, 128, 128, 256, 256, 256, 256, 256, 256, 256, 256, 256, 256, 256, 256, 256, 512, 512, 512, 512, 512, 512, 512]
def init_bn_state():
    return [(jnp.zeros(c, jnp.float32), jnp.ones(c, jnp.float32)) for c in _BN_CHANNELS]

def _drop_branch(branch, drop_key, keep_prob):
    # Inverted per-SAMPLE stochastic depth (timm DropPath): keep the whole
    # sample's residual branch w.p. keep_prob, scale survivors by 1/keep_prob
    # so inference (drop_key=None) is the identity. The (B,1,...,1) mask
    # broadcasts over every non-batch axis.
    # timm.layers.drop_path: shape = (x.shape[0],) + (1,) * (x.ndim - 1)
    if drop_key is None or keep_prob >= 1.0:
        return branch
    shape = (branch.shape[0],) + (1,) * (branch.ndim - 1)
    keep = jax.random.bernoulli(drop_key, keep_prob, shape).astype(branch.dtype)
    return branch * keep / keep_prob

def basic_block(params, x, idx, bn, bn_start, training):
    out, n0 = conv_bn(x, params[idx][0], params[idx][1], params[idx][2], bn[bn_start], training)
    out = jax.nn.relu(out)
    out, n1 = conv_bn(out, params[idx+1][0], params[idx+1][1], params[idx+1][2], bn[bn_start+1], training)
    return jax.nn.relu(out + x), [n0, n1]

def basic_block_down(params, x, idx, stride, bn, bn_start, training):
    out, n0 = conv_bn(x, params[idx][0], params[idx][1], params[idx][2], bn[bn_start], training, stride=(stride,stride))
    out = jax.nn.relu(out)
    out, n1 = conv_bn(out, params[idx+1][0], params[idx+1][1], params[idx+1][2], bn[bn_start+1], training)
    shortcut, n2 = conv_bn(x, params[idx+2][0], params[idx+2][1], params[idx+2][2], bn[bn_start+2], training, stride=(stride,stride))
    return jax.nn.relu(out + shortcut), [n0, n1, n2]

def global_avg_pool(x):
    return jnp.mean(x, axis=(2, 3))

