    """Xavier/Kaiming uniform init."""
    params = []
    # ConvBN 3→64, 7x7
    key, k_ = random.split(key)
    scale = jnp.sqrt(6.0 / 3136)
    params.append((random.uniform(k_, (64, 3, 7, 7), minval=-scale, maxval=scale),
                   jnp.ones(64), jnp.zeros(64)))
